DROP TABLE IF EXISTS `sys_dict_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_dict_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `dict_type` varchar(100) NOT NULL COMMENT '字典类型编码',
  `dict_label` varchar(100) NOT NULL COMMENT '字典标签(展示)',
  `dict_value` varchar(100) NOT NULL COMMENT '字典键值(存库)',
  `css_class` varchar(100) DEFAULT NULL COMMENT '前端标签样式:primary/success/warning/danger/info',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `is_default` tinyint NOT NULL DEFAULT '0' COMMENT '是否默认选中:0否 1是',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_type_value` (`tenant_id`,`dict_type`,`dict_value`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_type` (`tenant_id`,`dict_type`)
) ENGINE=InnoDB AUTO_INCREMENT=1386 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='租户字典数据';
/*!40101 SET character_set_client = @saved_cs_client */;

